select case when year(c.signup_date) < 2024 then 'before_2024' when year(c.signup_date) = 2024 then '2024' else 'after_2024' end signup_cohort, year(c.signup_date) signup_year, sum(oi.unit_price * oi.quantity) revenue from order_items oi inner join orders o on oi.order_id = o.id left join customers c on o.customer_id = c.id where c.city = 'Tokyo' group by case when year(c.signup_date) < 2024 then 'before_2024' when year(c.signup_date) = 2024 then '2024' else 'after_2024' end, year(c.signup_date) having revenue >= 51 order by signup_year asc, signup_cohort asc limit 10;
